diff --git a/solver_extensions/rv_component.h b/solver_extensions/rv_component.h
new file mode 100644
index 0000000..7e3a90e
--- /dev/null
+++ b/solver_extensions/rv_component.h
@@ -0,0 +1,403 @@
+// Register-value component of the statistical corrector.
+//
+// Availability tracking: every architectural destination (0..64) remembers the
+// identity of its youngest decoded producer. A value becomes usable only when
+// that same producer executes; an older producer executing later is ignored,
+// so a superseded value is never re-enabled.
+//
+// Prediction: two groups of tagless tables of signed counters feed the
+// corrector sum, each scaled by its own per-PC weight (0, 1, 2 or 3).
+//  - Recent group: the youngest decoded producers whose values are available
+//    (ranked by producer age) under several representations: a hash of the
+//    full value, the low eight bits and a logarithmic magnitude class,
+//    together with the flags register.
+//  - Selected group: each branch (PC hash) owns RVSlots register slots, each
+//    indexing a shared table with (PC, register, value or pending state; the
+//    last slot uses the magnitude class instead of the value). A slot earns
+//    credit when its counter is right while the rest of the corrector is
+//    wrong and loses credit in the opposite case or when both are wrong; only
+//    slots with positive credit vote. A slot that runs out of credit is
+//    replaced by the next register available at the prediction, so every
+//    branch walks through the registers looking for values that correlate
+//    with its direction.
+
+static constexpr int RVNumRegs = 65;
+static constexpr int RVFlagsReg = 64;
+static constexpr int RVRanks = 2;
+static constexpr int RVRecent = 6; // recent-group tables
+static constexpr int RVSlots = 3;
+static constexpr int RVClassSlots = 1;
+static constexpr int RVLogSlot = 11;
+static constexpr int RVLogSel = 8;
+static constexpr int RVLogW = 7;
+static constexpr int RVNumIdx = RVRecent + RVSlots;
+static constexpr int RVCtrMax = 31;
+static constexpr int RVCtrMin = -32;
+static constexpr int RVUseMax = 7;
+static constexpr int RVUseMin = -8;
+
+struct RVCounter {
+    int8_t v : 6;
+};
+
+struct RVReg {
+    uint32_t val; // 32-bit hash of the 64-bit value
+    uint32_t tag : 24; // youngest decoded producer (low bits of seq_no)
+    uint16_t cls : 10; // sign and logarithmic magnitude class of the value
+    uint8_t lo; // low eight bits of the value
+    uint8_t ready : 1; // youngest decoded producer has executed
+};
+
+struct RVSlot {
+    uint8_t r : 7; // selected register
+    int8_t use : 4; // credit of the selection
+};
+
+struct RVSel {
+    std::array<RVSlot, RVSlots> slot;
+};
+
+struct RVSnap {
+    std::array<uint16_t, RVNumIdx> idx; // recent tables, then the slots
+    std::array<uint8_t, RVSlots> sr; // selected registers at prediction
+    std::array<uint8_t, RVSlots> cand; // next available register after each slot
+    uint8_t vote : 3; // slots whose credit is positive
+};
+
+struct RVComponent {
+    std::array<std::array<RVCounter, 1024>, 1> big_tab; // recent table 0
+    std::array<std::array<RVCounter, 512>, RVRecent - 1> small_tab; // recent tables 1..
+    std::array<RVCounter, 1 << RVLogSlot> slot_tab;
+    std::array<RVSel, 1 << RVLogSel> sel;
+    std::array<std::array<RVCounter, 1 << RVLogW>, 2> wgt; // recent, selected
+    std::array<RVReg, RVNumRegs> reg;
+
+    static uint64_t mix(uint64_t x)
+    {
+        x ^= x >> 31;
+        x *= 0x9E3779B97F4A7C15ull;
+        x ^= x >> 29;
+        x *= 0xBF58476D1CE4E5B9ull;
+        x ^= x >> 32;
+        return x;
+    }
+
+    static int bitlen(uint64_t x)
+    {
+        int n = 0;
+        if ((x >> 32) != 0) {
+            n += 32;
+            x >>= 32;
+        }
+        if ((x >> 16) != 0) {
+            n += 16;
+            x >>= 16;
+        }
+        if ((x >> 8) != 0) {
+            n += 8;
+            x >>= 8;
+        }
+        if ((x >> 4) != 0) {
+            n += 4;
+            x >>= 4;
+        }
+        if ((x >> 2) != 0) {
+            n += 2;
+            x >>= 2;
+        }
+        if ((x >> 1) != 0) {
+            n += 1;
+            x >>= 1;
+        }
+        return n + (x & 1);
+    }
+
+    // bit length and the two bits below the leading one, with the sign
+    static int value_class(uint64_t v)
+    {
+        const bool neg = (v >> 63) != 0;
+        const uint64_t a = neg ? ~v : v;
+        int c = a;
+        if (a >= 4) {
+            const int n = bitlen(a);
+            c = 4 * n + ((a >> (n - 3)) & 3);
+        }
+        return neg ? 512 + c : c;
+    }
+
+    static int table_bits(int t)
+    {
+        if (t < 1)
+            return 10;
+        if (t < RVRecent)
+            return 9;
+        return RVLogSlot;
+    }
+
+    static uint16_t index_of(uint64_t pch, int t, uint64_t f)
+    {
+        const uint64_t salt = t < RVRecent ? t + 1 : RVRecent + 1;
+        return (mix(f ^ (salt << 58)) ^ pch) & ((1 << table_bits(t)) - 1);
+    }
+
+    static int windex(uint64_t PC)
+    {
+        return (PC ^ (PC >> 2) ^ (PC >> 9)) & ((1 << RVLogW) - 1);
+    }
+
+    static int sindex(uint64_t PC)
+    {
+        return (PC ^ (PC >> 2) ^ (PC >> (RVLogSel + 2))) & ((1 << RVLogSel) - 1);
+    }
+
+    void on_decode(uint64_t seq_no, uint64_t dst)
+    {
+        if (dst >= RVNumRegs)
+            return;
+        reg.at(dst).tag = seq_no & 0xFFFFFF;
+        reg.at(dst).ready = 0;
+    }
+
+    void on_execute(uint64_t seq_no, uint64_t dst, uint64_t v)
+    {
+        if (dst >= RVNumRegs)
+            return;
+        if (reg.at(dst).tag != (seq_no & 0xFFFFFF))
+            return; // superseded by a younger decoded producer
+        reg.at(dst).val = mix(v) & 0xFFFFFFFFull;
+        reg.at(dst).cls = value_class(v);
+        reg.at(dst).lo = v & 0xFF;
+        reg.at(dst).ready = 1;
+    }
+
+    // (register, value) or (register, pending) feature
+    uint64_t reg_feature(int r) const
+    {
+        const uint64_t id = r + 1;
+        if (reg.at(r).ready == 0)
+            return (id << 40) ^ 0xFFFFFFFFFFull;
+        return (id << 40) ^ reg.at(r).val;
+    }
+
+    // (register, magnitude class) or (register, pending) feature
+    uint64_t class_feature(int r) const
+    {
+        const uint64_t id = r + 1;
+        if (reg.at(r).ready == 0)
+            return (id << 40) ^ 0xFFFFFFFFFFull;
+        return (id << 40) ^ (0x40000000ull + reg.at(r).cls);
+    }
+
+    // (register, low eight bits) or (register, pending) feature
+    uint64_t low_feature(int r) const
+    {
+        const uint64_t id = r + 1;
+        if (reg.at(r).ready == 0)
+            return (id << 40) ^ 0xFFFFFFFFFFull;
+        return (id << 40) ^ (0x80000000ull + reg.at(r).lo);
+    }
+
+    bool selected(const RVSel& e, int r) const
+    {
+        for (int k = 0; k < RVSlots; ++k)
+            if (e.slot.at(k).r == r)
+                return true;
+        return false;
+    }
+
+    RVSnap make_snapshot(uint64_t seq_no, uint64_t PC) const
+    {
+        const uint64_t pch = mix(PC ^ (PC >> 2));
+        RVSnap s {};
+
+        // the RVRanks youngest decoded producers whose values are available
+        std::array<int, RVRanks> rr;
+        std::array<int, RVRanks> ra;
+        rr.fill(-1);
+        ra.fill(1 << 30);
+        for (int r = 0; r < RVNumRegs; ++r) {
+            if (reg.at(r).ready == 0)
+                continue;
+            const int age = (seq_no - reg.at(r).tag) & 0xFFFFFF;
+            if (age >= ra.at(RVRanks - 1))
+                continue;
+            int k = RVRanks - 1;
+            while (k > 0 && ra.at(k - 1) > age) {
+                ra.at(k) = ra.at(k - 1);
+                rr.at(k) = rr.at(k - 1);
+                --k;
+            }
+            ra.at(k) = age;
+            rr.at(k) = r;
+        }
+        std::array<uint64_t, RVRanks> fv;
+        std::array<uint64_t, RVRanks> fc;
+        std::array<uint64_t, RVRanks> fl;
+        for (int j = 0; j < RVRanks; ++j) {
+            const int r = rr.at(j);
+            if (r < 0) {
+                fv.at(j) = 0x5555 + j;
+                fc.at(j) = 0x777 + j;
+                fl.at(j) = 0x999 + j;
+            } else {
+                fv.at(j) = reg_feature(r);
+                fc.at(j) = class_feature(r);
+                fl.at(j) = low_feature(r);
+            }
+        }
+        s.idx.at(0) = index_of(pch, 0, fv.at(0));
+        s.idx.at(1) = index_of(pch, 1, fl.at(0));
+        s.idx.at(2) = index_of(pch, 2, fc.at(0));
+        s.idx.at(3) = index_of(pch, 3, fv.at(1));
+        s.idx.at(4) = index_of(pch, 4, fc.at(1));
+        s.idx.at(5) = index_of(pch, 5, reg_feature(RVFlagsReg));
+
+        // selected registers of this branch
+        const RVSel e = sel.at(sindex(PC));
+        s.vote = 0;
+        for (int k = 0; k < RVSlots; ++k) {
+            const int r = e.slot.at(k).r;
+            s.sr.at(k) = r;
+            if (e.slot.at(k).use > 0)
+                s.vote |= 1 << k;
+            const uint64_t f = k < RVSlots - RVClassSlots ? reg_feature(r) : class_feature(r);
+            s.idx.at(RVRecent + k) = index_of(pch, RVRecent + k, f);
+        }
+
+        // replacement candidates: the next available unselected register
+        // after each slot, so that every slot walks through the registers
+        for (int k = 0; k < RVSlots; ++k) {
+            int c = e.slot.at(k).r;
+            for (int n = 0; n < RVNumRegs; ++n) {
+                c = c + RVSlots >= RVNumRegs ? c + RVSlots - RVNumRegs : c + RVSlots;
+                if (reg.at(c).ready != 0 && !selected(e, c))
+                    break;
+            }
+            s.cand.at(k) = c;
+        }
+        return s;
+    }
+
+    int counter_at(const RVSnap& s, int t) const
+    {
+        if (t < 1)
+            return big_tab.at(t).at(s.idx.at(t)).v;
+        if (t < RVRecent)
+            return small_tab.at(t - 1).at(s.idx.at(t)).v;
+        return slot_tab.at(s.idx.at(t)).v;
+    }
+
+    void counter_update(const RVSnap& s, int t, bool taken)
+    {
+        int c = counter_at(s, t);
+        if (taken) {
+            if (c < RVCtrMax)
+                ++c;
+        } else {
+            if (c > RVCtrMin)
+                --c;
+        }
+        if (t < 1)
+            big_tab.at(t).at(s.idx.at(t)).v = c;
+        else if (t < RVRecent)
+            small_tab.at(t - 1).at(s.idx.at(t)).v = c;
+        else
+            slot_tab.at(s.idx.at(t)).v = c;
+    }
+
+    bool votes(const RVSnap& s, int t) const
+    {
+        return t < RVRecent || ((s.vote >> (t - RVRecent)) & 1) != 0;
+    }
+
+    // raw sum of group g: 0 recent, 1 selected
+    int group_sum(const RVSnap& s, int g) const
+    {
+        int sum = 0;
+        const int lo = g == 0 ? 0 : RVRecent;
+        const int hi = g == 0 ? RVRecent : RVNumIdx;
+        for (int t = lo; t < hi; ++t)
+            if (votes(s, t))
+                sum += 2 * counter_at(s, t) + 1;
+        return sum;
+    }
+
+    int mult(uint64_t PC, int g) const
+    {
+        const int w = wgt.at(g).at(windex(PC)).v;
+        return w >= 16 ? 3 : (w >= 4 ? 2 : (w >= -8 ? 1 : 0));
+    }
+
+    int contribution(const RVSnap& s, uint64_t PC) const
+    {
+        return mult(PC, 0) * group_sum(s, 0) + mult(PC, 1) * group_sum(s, 1);
+    }
+
+    int group_extra(uint64_t PC) const
+    {
+        return mult(PC, 0) >= 2 || mult(PC, 1) >= 2 ? 2 : 0;
+    }
+
+    void weight_update(uint64_t PC, int g, int sum, int lsum, bool taken)
+    {
+        const int rest = lsum - mult(PC, g) * sum;
+        if ((rest >= 0) == (rest + 2 * sum >= 0))
+            return;
+        const int wi = windex(PC);
+        int w = wgt.at(g).at(wi).v;
+        if ((sum >= 0) == taken) {
+            if (w < RVCtrMax)
+                ++w;
+        } else {
+            if (w > RVCtrMin)
+                --w;
+        }
+        wgt.at(g).at(wi).v = w;
+    }
+
+    void select_update(const RVSnap& s, uint64_t PC, bool taken, int lsum, int m)
+    {
+        const int si = sindex(PC);
+        RVSel e = sel.at(si);
+        bool replaced = false;
+        for (int k = 0; k < RVSlots; ++k) {
+            if (e.slot.at(k).r != s.sr.at(k))
+                continue; // selection changed since this prediction
+            bool dup = false;
+            for (int q = 0; q < k; ++q)
+                if (e.slot.at(q).r == e.slot.at(k).r)
+                    dup = true;
+            const int c = 2 * counter_at(s, RVRecent + k) + 1;
+            const int rest = votes(s, RVRecent + k) ? lsum - m * c : lsum;
+            const bool ok = (c >= 0) == taken;
+            const bool rest_ok = (rest >= 0) == taken;
+            int u = e.slot.at(k).use;
+            if (ok && !rest_ok)
+                u += 2;
+            else if (!ok && rest_ok)
+                u -= 2;
+            else if (!ok)
+                u -= 1;
+            u = u > RVUseMax ? RVUseMax : (u < RVUseMin ? RVUseMin : u);
+            if ((u <= RVUseMin || dup) && !replaced && !selected(e, s.cand.at(k))) {
+                e.slot.at(k).r = s.cand.at(k);
+                u = 0;
+                replaced = true;
+            }
+            e.slot.at(k).use = u;
+        }
+        sel.at(si) = e;
+    }
+
+    void train(const RVSnap& s, uint64_t PC, bool taken, int lsum)
+    {
+        const int sum0 = group_sum(s, 0);
+        const int sum1 = group_sum(s, 1);
+        const int m1 = mult(PC, 1);
+        weight_update(PC, 0, sum0, lsum, taken);
+        weight_update(PC, 1, sum1, lsum, taken);
+        select_update(s, PC, taken, lsum, m1);
+        for (int t = 0; t < RVNumIdx; ++t)
+            counter_update(s, t, taken);
+    }
+};
